export async function getOwnedMarketingOrder(orderId: string) {
  const session = await requireSession();

  const rows = await controlDb
    .select({
      order: reportAccessOrders,
      purchaseIntent: purchaseIntents,
      entitlement: consultationEntitlements,
    })
    .from(reportAccessOrders)
    .leftJoin(
      purchaseIntents,
      eq(purchaseIntents.orderId, reportAccessOrders.id),
    )
    .leftJoin(
      consultationEntitlements,
      eq(consultationEntitlements.orderId, reportAccessOrders.id),
    )
    .where(
      and(
        eq(reportAccessOrders.id, orderId),
        eq(reportAccessOrders.buyerUserId, session.user.id),
        isNull(reportAccessOrders.deletedAt),
      ),
    )
    .limit(1);

  return rows[0] ?? null;
}
